-- Lookup helper used by Tooltip.lua and Assistance.lua. Returns nil for
-- absent rows so callers can fall through to legacy behavior unchanged.
function M:GetReagentMetadata(itemID)
    if not itemID then return nil end
    return self.ReagentMetadata and self.ReagentMetadata[itemID] or nil
end

-- Convenience: which gathering profession produces this reagent (if any).
function M:GetReagentGatheringProf(itemID)
    local meta = self:GetReagentMetadata(itemID)
    return meta and meta.gatheringProf or nil
end

-- Convenience: what color tint this reagent uses for its quality bar.
function M:GetReagentColor(itemID)
    local meta = self:GetReagentMetadata(itemID)
    return meta and meta.color or nil
end

-- Which professions consume this reagent. Drives the Inventory tab's "Used In"
-- column for materials no known recipe references yet.
function M:GetReagentProcessingProfs(itemID)
    local meta = self:GetReagentMetadata(itemID)
    return meta and meta.processingProfs or nil
end
